import Link from "next/link";
import { getFullMedia } from "@/lib/server-api";
import MovieDetails from "@/components/MovieDetails";
import MusicDetails from "@/components/MusicDetails";
import AddToWatchPop from "@/components/AddToWatchpopButton";

export default async function MediaPage({
  params,
}: {
  params: Promise<{ type: string; id: string }>;
}) {
  const { type, id } = await params;
  const media = await getFullMedia(type, id);

  const isAdded = !!media.user_entry;
  const friends =
    typeof media.user_entry?.friends_recommended === "string"
      ? media.user_entry.friends_recommended
          .split(",")
          .map((f: string) => f.trim())
          .filter(Boolean)
      : [];

  const tags =
    typeof media.user_entry?.my_tags === "string"
      ? media.user_entry.my_tags
          .split(",")
          .map((t: string) => t.trim())
          .filter(Boolean)
      : [];

  return (
    <div className="relative max-w-6xl mx-auto px-6 md:px-8 pt-8 pb-32 text-zinc-100">
      {/* Background */}
      {media.poster && (
        <div
          className="absolute inset-0 -z-10 bg-cover bg-center opacity-10 blur-3xl"
          style={{ backgroundImage: `url(${media.poster})` }}
        />
      )}
      <div className="absolute inset-0 -z-10 bg-gradient-to-b from-black/40 via-black/70 to-black" />

      {/* Back Button */}
      <div className="mb-10">
        <Link
          href="/discover"
          className="text-sm text-zinc-400 hover:text-zinc-200 transition"
        >
          ← Back
        </Link>
      </div>

      {/* HERO */}
      <section className="flex flex-col md:flex-row gap-14 items-start">
        {media.poster && (
          <div className="shrink-0">
            <img
              src={media.poster}
              alt={media.title}
              className="w-64 md:w-72 rounded-3xl shadow-2xl object-cover"
            />
          </div>
        )}

        <div className="flex-1 max-w-3xl">
          <h1 className="text-4xl md:text-5xl font-semibold tracking-tight leading-tight">
            {media.title}
          </h1>

          {media.subtitle && (
            <p className="mt-4 text-zinc-400 text-lg">{media.subtitle}</p>
          )}

          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-zinc-500">
            {media.genre && <span>{media.genre}</span>}
            {media.release_date && <span>{media.release_date}</span>}
          </div>

          {/* Add Button */}
          <div className="mt-10">
            <AddToWatchPop
              item={{ id, title: media.title }}
              type={type as "movie" | "music"}
              isAdded={isAdded}
            />
          </div>

          {/* PERSONAL METADATA (No Box) */}
          {media.user_entry && (
            <div className="mt-10 space-y-6">
              {media.user_entry.rating && (
                <div className="flex items-center gap-3">
                  <span className="text-xs tracking-widest uppercase text-zinc-500">
                    Your Rating
                  </span>

                  <div className="flex gap-1">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span
                        key={star}
                        className={`text-lg ${
                          star <= media.user_entry.rating
                            ? "text-yellow-400/80"
                            : "text-zinc-600"
                        }`}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {friends.length > 0 && (
                <div>
                  <p className="text-xs tracking-widest text-zinc-500 uppercase mb-4">
                    Recommended By
                  </p>

                  <div className="flex flex-wrap gap-2">
                    {friends.map((f: string) => (
                      <a
                        key={f}
                        href={`/recommended?friends_recommended=${encodeURIComponent(f)}`}
                        className="px-3 py-1.5 text-xs rounded-full
                                 bg-white/5 border border-white/10
                                 hover:bg-white/10 transition"
                      >
                        {f}
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </section>

      {/* OVERVIEW */}
      {media.description && (
        <section className="mt-24 max-w-3xl">
          <div className="border-t border-zinc-800 pt-12">
            <p className="text-xs tracking-widest text-zinc-500 uppercase mb-8">
              Overview
            </p>

            <p className="text-zinc-400 leading-relaxed text-[15px]">
              {media.description}
            </p>
          </div>
        </section>
      )}

      {/* USER TAGS */}
      {tags.length > 0 && (
        <section className="mt-16">
          <p className="text-xs tracking-widest text-zinc-500 uppercase mb-5">
            Your Tags
          </p>

          <div className="flex flex-wrap gap-2">
            {tags.map((tag: string) => {
              const href =
                type === "movie"
                  ? `/library/movies?my_tag=${encodeURIComponent(tag)}`
                  : `/library/music?my_tags=${encodeURIComponent(tag)}`;

              return (
                <a
                  key={tag}
                  href={href}
                  className="px-3 py-1.5 text-xs rounded-full
                           bg-white/5 border border-white/10
                           hover:bg-white/10 transition
                           hover:scale-105 active:scale-95"
                >
                  #{tag}
                </a>
              );
            })}
          </div>
        </section>
      )}

      {/* TYPE-SPECIFIC DETAILS */}
      <section className="mt-24 space-y-16">
        {type === "movie" && <MovieDetails data={media.provider_data} />}
        {type === "music" && <MusicDetails data={media.provider_data} />}
      </section>
    </div>
  );
}
